SCHEMA = json.loads(_SCHEMA_JSON)
MOTION_VERSION = 'gq_shared_motion_prefix_v1'
ROLES = ('dual_neg45', 'dual_pos45')
DT = .05
_UNIT_TOKEN = object()


def _plain(value):
    if type(value) is dict:
        if any(type(k) is not str for k in value): raise ContractError('String JSON keys required')
        for item in value.values(): _plain(item)
    elif type(value) is list:
        for item in value: _plain(item)
    elif type(value) is float:
        if not math.isfinite(value): raise ContractError('Nonfinite value')
    elif value is None or type(value) in (str, int, bool):
        return
    else: raise ContractError('Only plain typed JSON values are accepted')


def _matches(value, schema):
    try:
        _check(value, schema)
        return True
    except ContractError:
        return False


def _check(value, schema, path=''):
    if schema is True: return
    if schema is False: raise ContractError(path+': forbidden schema value')
    if '$ref' in schema:
        name = schema['$ref'].split('/')[-1]
        if name == 'FiniteFloat' and type(value) is not float:
            raise ContractError(path+': exact float required')
        _check(value, SCHEMA['$defs'][name], path)
    if 'const' in schema and typed_digest(value) != typed_digest(schema['const']):
        raise ContractError(path+': constant mismatch')
    if 'enum' in schema and not any(typed_digest(value) == typed_digest(v) for v in schema['enum']):
        raise ContractError(path+': enum mismatch')
    for sub in schema.get('allOf', []): _check(value, sub, path)
    for name in ('anyOf', 'oneOf'):
        if name in schema:
            count = sum(_matches(value, sub) for sub in schema[name])
            if count < 1 or name == 'oneOf' and count != 1:
                raise ContractError(path+': '+name+' mismatch')
    if 'if' in schema:
        branch = 'then' if _matches(value, schema['if']) else 'else'
        if branch in schema: _check(value, schema[branch], path)
    kind = schema.get('type')
    kinds = {'object': type(value) is dict, 'array': type(value) is list,
             'integer': type(value) is int, 'number': type(value) in (int, float),
             'string': type(value) is str, 'boolean': type(value) is bool, 'null': value is None}
    if kind is not None and not kinds.get(kind, False): raise ContractError(path+': type '+kind)
    if type(value) is dict:
        props = schema.get('properties', {})
        if any(k not in value for k in schema.get('required', [])): raise ContractError(path+': missing field')
        extra = set(value)-set(props)
        if schema.get('additionalProperties') is False and extra: raise ContractError(path+': unknown field')
        for k, item in value.items():
            part = k.replace('~', '~0').replace('/', '~1')
            if k in props: _check(item, props[k], path+'/'+part)
            elif isinstance(schema.get('additionalProperties'), dict):
                _check(item, schema['additionalProperties'], path+'/'+part)
    if type(value) is list:
        if not schema.get('minItems', 0) <= len(value) <= schema.get('maxItems', math.inf):
            raise ContractError(path+': array length')
        if schema.get('uniqueItems') and len({typed_digest(v) for v in value}) != len(value):
            raise ContractError(path+': duplicate array entry')
        prefix = schema.get('prefixItems', [])
        for i, item in enumerate(value):
            if i < len(prefix): _check(item, prefix[i], path+'/'+str(i))
            elif 'items' in schema: _check(item, schema['items'], path+'/'+str(i))
    if type(value) is str:
        if not schema.get('minLength', 0) <= len(value) <= schema.get('maxLength', math.inf):
            raise ContractError(path+': string length')
        if 'pattern' in schema and re.search(schema['pattern'], value) is None:
            raise ContractError(path+': string pattern')
    if type(value) in (int, float):
        if value < schema.get('minimum', -math.inf) or value > schema.get('maximum', math.inf):
            raise ContractError(path+': numeric bounds')


def validate_definition(value, name):
    if name not in SCHEMA['$defs']: raise ContractError('Unknown shared definition')
    _plain(value)
    if name == 'FiniteFloat' and type(value) is not float: raise ContractError('Exact float required')
    _check(value, SCHEMA['$defs'][name])
    return deepcopy(value)


def f64hex(value):
    if type(value) is not float or not math.isfinite(value): raise ContractError('Finite float required')
    return struct.pack('>d', value).hex()


def _fresh_profiles(flat):
    profiles = flat['sensor_profiles'];x = flat['config']['robots'];tick = flat['start_tick']
    if len(profiles) != x or [p['sensor_id'] for p in profiles] != ['U'+str(i) for i in range(x)]:
        raise ContractError('One sensor profile per stable Uk required')
    if any(type(p['observed_tick']) is not int or p['observed_tick'] != tick for p in profiles):
        raise ContractError('Stale sensor profile: refusal without timestamp repair')


def _flat_check(flat):
    from pursuit_v2.config import Config
    from research.information_service_online import public
    fields = {'config', 'start_tick', 'prediction_end_tick', 'positions', 'assignment',
              'targets', 'sensor_profiles', 'gq_histories'}
    if type(flat) is not dict or set(flat) != fields: raise ContractError('Exact flat unit request fields required')
    _plain(flat);cfg = Config(**flat['config']);start = flat['start_tick'];end = flat['prediction_end_tick']
    if type(start) is not int or type(end) is not int or not 0 <= start < end <= min(start+60, round(cfg.end_time/DT)):
        raise ContractError('Invalid unit time window')
    if len(flat['positions']) != cfg.robots or len(flat['assignment']) != cfg.robots:
        raise ContractError('Full independent robot arrays required')
    for p in flat['positions']: validate_definition(p, 'Vector2')
    for p in flat['sensor_profiles']: public.validate_schema(p, 'SensorProfile')
    _fresh_profiles(flat)
    ids = [t['id'] for t in flat['targets']]
    if ids != sorted(set(ids)) or any(type(j) is not int or not 0 <= j < cfg.task_count for j in ids):
        raise ContractError('Invalid visible target identity')
    for t in flat['targets']:
        if t['required_robots'] != 2: raise ContractError('Shared-full first round requires q=2')
        for p in (t['position_now'], t['velocity_now']): validate_definition(p, 'Vector2')
        if t['birth'] > start*DT+1e-10: raise ContractError('Hidden task in unit request')
    if [h['target_id'] for h in flat['gq_histories']] != ids:
        raise ContractError('One ordered unit history per target required')
    return deepcopy(flat)


class UnitFixtureCapability:
    """Explicit test factory product; never recognized as real-history authority."""
    __slots__ = ('_fixture_id', '_request', '_manifest', '_fingerprint')
    def __init__(self, fixture_id, request, manifest, *, _token=None):
        if _token is not _UNIT_TOKEN: raise ContractError('Unit capability requires explicit factory')
        object.__setattr__(self, '_fixture_id', fixture_id)
        object.__setattr__(self, '_request', deepcopy(request))
        object.__setattr__(self, '_manifest', deepcopy(manifest))
        object.__setattr__(self, '_fingerprint', typed_digest(request))
    def __setattr__(self, name, value): raise ContractError('Immutable fixture capability')
    @property
    def request(self): return deepcopy(self._request)
    @property
    def manifest(self): return deepcopy(self._manifest)
    @property
    def fixture_id(self): return self._fixture_id


def make_unit_fixture(fixture_id, fixture):
    """Test factory accepts declared input only, never expected/oracle material."""
    if type(fixture_id) is not str or not fixture_id: raise ContractError('Explicit unit fixture id required')
    _plain(fixture)
    if fixture.get('message_kind') == 'evaluation_request':
        from research.information_service_online.adapter import flatten_request
        flat, original = flatten_request(fixture, unit_only=True)
        flat = _flat_check(flat)
        manifest = deepcopy(original)
        # Retain public metadata for test-only full assembly, never as actual admission.
        manifest['unit_public_request'] = deepcopy(original['payload'])
    else:
        if 'fixture' in fixture or 'expected' in fixture or 'events' in fixture:
            raise ContractError('Factory needs only input.fixture, never checker/oracle wrapper')
        if 'gq_histories' in fixture:
            flat = _flat_check(fixture)
        else:
            allowed = {'provenance','config','start_tick','prediction_end_tick','episode_end_tick',
                'positions','targets','assignment','sensor_profiles','synthetic_clock','unit_window_override',
                'synthetic_retained_endpoint'}
            if set(fixture)-allowed: raise ContractError('Unknown logical unit-fixture field')
            needed = {'config','start_tick','prediction_end_tick','positions','targets','assignment','sensor_profiles','synthetic_clock'}
            if not needed <= set(fixture): raise ContractError('Incomplete logical unit fixture')
            flat = {k:deepcopy(fixture[k]) for k in needed if k != 'synthetic_clock'}
            clock = fixture['synthetic_clock'];assigned = {a['target'] for a in fixture['assignment'] if a['target'] is not None}
            if clock['team'] and len(assigned) != 1: raise ContractError('Synthetic clock needs one explicit assigned task')
            histories = []
            for target in fixture['targets']:
                active = target['id'] in assigned
                c = deepcopy(clock) if active else {'base':0., 'intervals':0, 'team':[]}
                endpoint = deepcopy(fixture.get('synthetic_retained_endpoint')) if active else None
                if endpoint is not None:
                    if endpoint.get('tick') != fixture['start_tick']: raise ContractError('Synthetic endpoint is not current')
                    endpoint = {k:endpoint[k] for k in ('tick','G','Q')}
                histories.append({'target_id':target['id'], 'clock_state':c, 'last_endpoint':endpoint,
                                  'mode':'explicit_unit_fixture', 'public_history_sha256':None})
            flat['gq_histories'] = histories;flat = _flat_check(flat)
        request_id = digest({'unit_fixture_id':fixture_id, 'flat_request':flat})
        world = digest({'unit_fixture_id':fixture_id, 'request_identity':request_id, 'forecast':'public_cv_sigma_hold_zero_noise_v1'})
        specs = []
        for target in flat['targets']:
            for robots in combinations(range(flat['config']['robots']), 2):
                for roles in permutations(ROLES):
                    key = {'target':target['id'], 'robots':list(robots), 'roles':list(roles)}
                    identity = {'evaluation_request_id':request_id, 'world_id':world, 'key':key}
                    specs.append({'message_kind':'candidate_descriptor', **identity,
                        'candidate_id':digest(identity), 'index':len(specs), 'resource_mask':sum(1<<i for i in robots)})
        manifest = {'payload':deepcopy(flat), 'request_identity':request_id, 'world_identity':world,
                    'candidate_count':len(specs), 'candidates':specs}
    return UnitFixtureCapability(fixture_id, flat, manifest, _token=_UNIT_TOKEN)


def admit_request(request, *, history_authority=None, unit_fixture=None):
    if unit_fixture is not None:
        if type(unit_fixture) is not UnitFixtureCapability or history_authority is not None:
            raise ContractError('Explicit unit capability cannot mix with real authority')
        if typed_digest(request) != unit_fixture._fingerprint: raise ContractError('Unit capability/request mismatch')
        flat = _flat_check(request)
        return flat, unit_fixture.manifest
    from research.information_service_online import public
    from research.information_service_online.adapter import flatten_request
    if type(history_authority) is not public.HistoryAuthority:
        raise ContractError('Main shared evaluation requires externally admitted history')
    flat, manifest = flatten_request(request, authority=history_authority)
    if typed_digest(request) != typed_digest(manifest['payload']):
        raise ContractError('Main admission would normalize supplied types or bytes')
    if any(t['required_robots'] != 2 for t in flat['targets']): raise ContractError('First-round shared q=2 only')
    _fresh_profiles(flat)
    return flat, manifest


def select_descriptor(manifest, spec):
    if type(spec) is not dict: raise ContractError('Candidate mapping required')
    matches = []
    for candidate in manifest['candidates']:
        if 'candidate_id' in spec:
            same = typed_digest(spec) == typed_digest(candidate)
        else:
            fields = {'index','target','robots','roles'}
            same = fields <= set(spec) and spec['index'] == candidate['index'] and all(spec[k] == candidate['key'][k] for k in ('target','robots','roles'))
            # Internal numerical/short aliases do not authorize an altered identity.
            allowed = fields | {'mask','structural_key','candidate_identity','request_identity','world_identity'}
            if set(spec)-allowed: same = False
            checks = {'mask':candidate['resource_mask'],'structural_key':candidate['key'],
                'candidate_identity':candidate['candidate_id'],'request_identity':candidate['evaluation_request_id'],'world_identity':candidate['world_id']}
            if any(k in spec and typed_digest(spec[k]) != typed_digest(v) for k,v in checks.items()): same = False
        if same: matches.append(candidate)
    if len(matches) != 1: raise ContractError('Candidate not in canonical manifest')
    return deepcopy(matches[0])


def make_scope(request, *, attempt_id, decision_id, batch_id, cache_instance_id,
               runtime_binding_id, history_authority=None, unit_fixture=None):
    flat, manifest = admit_request(request, history_authority=history_authority, unit_fixture=unit_fixture)
    scope = {'message_kind':'motion_cache_scope','contract_id':STAGE_CONTRACT,
        'runtime_binding_id':runtime_binding_id,'scope_kind':'UNIT_ONLY' if unit_fixture is not None else 'MAIN_RUNTIME',
        'unit_fixture_id':unit_fixture.fixture_id if unit_fixture is not None else None,
        'attempt_id':attempt_id,'decision_id':decision_id,'batch_id':batch_id,'cache_instance_id':cache_instance_id,
        'evaluation_request_id':manifest['request_identity'],'world_id':manifest['world_identity'],
        'motion_geometry_contract_version':MOTION_VERSION,'config_digest':digest(flat['config']),
        'start_tick':flat['start_tick'],'prediction_end_tick':flat['prediction_end_tick'],
        'robots':flat['config']['robots'],'task_count':flat['config']['task_count']}
    scope['full_scope_id'] = typed_digest(scope)
    return validate_definition(scope, 'CacheScope')


def admit_scope(scope, request, *, history_authority=None, unit_fixture=None):
    scope = validate_definition(scope, 'CacheScope')
    flat, manifest = admit_request(request, history_authority=history_authority, unit_fixture=unit_fixture)
    if scope['full_scope_id'] != typed_digest({k:v for k,v in scope.items() if k != 'full_scope_id'}):
        raise ContractError('Cache scope identity mismatch')
    expected = {'scope_kind':'UNIT_ONLY' if unit_fixture is not None else 'MAIN_RUNTIME',
        'unit_fixture_id':unit_fixture.fixture_id if unit_fixture is not None else None,
        'evaluation_request_id':manifest['request_identity'],'world_id':manifest['world_identity'],
        'start_tick':flat['start_tick'],'prediction_end_tick':flat['prediction_end_tick'],
        'robots':flat['config']['robots'],'task_count':flat['config']['task_count'],'config_digest':digest(flat['config'])}
    if any(typed_digest(scope[k]) != typed_digest(v) for k,v in expected.items()):
        raise ContractError('Scope does not bind this exact request/capability')
    return scope, flat, manifest
